import{_ as a,o,c as n,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Governing Board - Public Session 2026-07-28","description":"","frontmatter":{"title":"Ceph Governing Board - Public Session 2026-07-28","outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Governing_Board_-_Public_Session_2026-07-28.md","filePath":"posts/2026/Ceph_Governing_Board_-_Public_Session_2026-07-28.md","lastUpdated":null}'),t={name:"posts/2026/Ceph_Governing_Board_-_Public_Session_2026-07-28.md"};function r(l,e,h,s,p,d){return o(),n("div",null,[...e[0]||(e[0]=[i('<p>I&#39;ll format the meeting minutes in Chinese following the standard structure.--- title: Ceph Governing Board- Public Session 2026-07-28 date: 2026-07-28 updated: 2026-07-29 tags:</p><ul><li>社区动态</li><li>会议纪要</li><li>Ceph</li><li>开源 categories:</li><li>视频总结 subtitle: Ceph_Governing_Board_-_Public_Session_2026-07-28</li></ul><hr><h1 id="ceph-治理委员会公开会议纪要-2026-07-28" tabindex="-1">Ceph 治理委员会公开会议纪要（2026-07-28） <a class="header-anchor" href="#ceph-治理委员会公开会议纪要-2026-07-28" aria-label="Permalink to &quot;Ceph 治理委员会公开会议纪要（2026-07-28）&quot;">​</a></h1><p>本次会议是 Ceph Governing Board 的首次公开董事会会议，于太平洋时间上午 10: 24 正式开始，10-34 结束。会议开场重申了 Linux Foundation（LF）反垄断合规声明，如有相关疑问可直接联系会议主持人。董事会成员与上次会议相比没有变化。</p><h2 id="一、会议流程概览" tabindex="-1">一、会议流程概览 <a class="header-anchor" href="#一、会议流程概览" aria-label="Permalink to &quot;一、会议流程概览&quot;">​</a></h2><p>由于这是首次公开会议，会议按照如下议程推进：会议纪要、预算简报、旧事项与新事项、各委员会报告，以及自由讨论时间。其中委员会报告占据了本次会议的主要时间。</p><h2 id="二、预算简报" tabindex="-1">二、预算简报 <a class="header-anchor" href="#二、预算简报" aria-label="Permalink to &quot;二、预算简报&quot;">​</a></h2><p>会议对基金会预算进行了高层次回顾。截至当前时点（数据实际截止到 6 月），没有预测到任何超支（no overages forecast）。总体而言，基金会在 2026 年预测的收入进展符合预期，处于正常轨道上。</p><h2 id="三、旧事项与新事项" tabindex="-1">三、旧事项与新事项 <a class="header-anchor" href="#三、旧事项与新事项" aria-label="Permalink to &quot;三、旧事项与新事项&quot;">​</a></h2><p>由于本次是首次公开会议，既没有需要回顾的既往会议纪要，也没有旧事项和新事项需要讨论，因此直接进入委员会报告环节。</p><h2 id="四、委员会报告" tabindex="-1">四、委员会报告 <a class="header-anchor" href="#四、委员会报告" aria-label="Permalink to &quot;四、委员会报告&quot;">​</a></h2><h3 id="_1-ceph-io-网站与市场推广-anthony" tabindex="-1">1. ceph.io 网站与市场推广（Anthony） <a class="header-anchor" href="#_1-ceph-io-网站与市场推广-anthony" aria-label="Permalink to &quot;1. ceph.io 网站与市场推广（Anthony）&quot;">​</a></h3><p>自上次会议以来，Anthony 主要围绕 ceph.io 网站进行了一系列更新：</p><ul><li><strong>Crimson 项目页面迁移</strong>：与 Matthias 沟通后，Crimson 项目页面被重新安置到网站的开发者（developer）板块，对方对此没有异议。</li><li><strong>清理过时内容</strong>：移除了来自 Index Exchange 等已经过期的招聘信息，并会确保相关页面保持更新；移除了过时的 2021 年 Red Hat Developer Report，替换为更适合开发者的学习工具链接。</li><li><strong>IRC 渠道调整</strong>：将 IRC 这一社交渠道从网站上撤下。原因是当前基金会没有专人对其进行监控（虽然基金会内部仍有人在使用）。社区成员仍被鼓励继续使用 IRC，Anthony 也无权关闭该服务器；网站上改为推广其他社交媒体渠道及访问方式。</li><li><strong>技术奖项页面</strong>：新建了技术奖项（technical award）获奖者页面并同步到社交媒体，最新一批获奖者来自 CephDays London。</li></ul><p><strong>Ceph Foundation 宣传材料（pitch deck）</strong>：Anthony 在过去几周持续制作基金会的宣传演示文稿，目前已有草稿并提供了链接，讲述 Ceph 是什么、Ceph Foundation 现状，以及未来如何成长、其他组织如何参与。他希望董事会成员尽快审阅并反馈改进意见。</p><p><strong>8 月计划</strong>：8 月不举办 Ceph Tech Talk，改为围绕「client summer break（客户暑期）」做一次推广活动，分享 YouTube 频道上较受欢迎的视频内容。他还计划借此机会扩充教育类内容：由于 ceph.io 上现有教育视频不多，他打算单独建立一个教育内容页面，讲解 Ceph 的基础知识；具体做法是将 Sage 几年前录制、至今仍然适用的一段视频拆分成若干小节，分类放置到网站上。</p><p><strong>Q3 会议安排</strong>：需要为第三季度的 CSC 与基金会董事会会议选定日期，计划放在季度末，并避开选举周期（election cycle）的干扰。</p><p><strong>讨论</strong>：Neha 提醒，IRC 与 Slack 之间存在一座桥接（bridge），有社区成员在主动维护，建议 Anthony 在邮件列表上发帖告知，避免他们对此变更措手不及。Anthony 回应称，在做出改动前已在 general 频道发帖，并与几位社区成员（尤其是 IRC 的管理员）沟通过，确认他们仍可自由继续使用 IRC，网站上移除链接的说明也已同步到 general 频道的相关话题下。</p><h3 id="_2-ceph-days-活动-tim-neha-anthony" tabindex="-1">2. Ceph Days 活动（Tim / Neha / Anthony） <a class="header-anchor" href="#_2-ceph-days-活动-tim-neha-anthony" aria-label="Permalink to &quot;2. Ceph Days 活动（Tim / Neha / Anthony）&quot;">​</a></h3><ul><li><strong>韩国（Korea）</strong>：当地社区成员正与另外两个开源项目筹备一次联合活动，计划在 9 月举行。CFP（议题征集）已完成，报名情况良好，主要面向同期参加某相邻活动的与会者。</li><li><strong>Ceph Days Zurich（苏黎世）</strong>：定于 10 月举行。</li><li><strong>Ceph Days Chicago（芝加哥）</strong>：定于 11 月举行，Neha 是筹备委员会成员之一。目前已建立 Slack 频道，欢迎有兴趣者加入；此次活动由三个组织联合筹办，并与超级计算大会（supercomputing）同周举行。T 恤设计方案已有若干候选。</li><li><strong>Ceph Days Berlin（柏林）</strong>：主办方计划放到 2027 年举办，Anthony 表示基金会将提供力所能及的支持。此外还有一些暂定活动可能进入 2027 年，视具体进展而定。</li></ul><h3 id="_3-大使计划-ambassadors-与-ceph-developer-summit-anthony" tabindex="-1">3. 大使计划（Ambassadors）与 Ceph Developer Summit（Anthony） <a class="header-anchor" href="#_3-大使计划-ambassadors-与-ceph-developer-summit-anthony" aria-label="Permalink to &quot;3. 大使计划（Ambassadors）与 Ceph Developer Summit（Anthony）&quot;">​</a></h3><ul><li><strong>大使计划</strong>：计划在 9 月安排第三季度会议，选定日期后会在会后提交报告。</li><li><strong>Ceph Developer Summit</strong>：与 CSC 合作推进，日期已调整为 8 月 4 日至 8 月 13 日。大部分组件负责人（component leads）的分会场已排定，本周将开始在社交渠道进行推广。所有分会场都会录制并事后分享到 YouTube 频道。会议还提到了 Vampire 版本相关的内容。</li></ul><h2 id="五、其他事项与决定" tabindex="-1">五、其他事项与决定 <a class="header-anchor" href="#五、其他事项与决定" aria-label="Permalink to &quot;五、其他事项与决定&quot;">​</a></h2><p>会议没有其他新增业务。</p><p><strong>关键决定与后续行动：</strong></p><ul><li>IRC 链接从 ceph.io 撤下，社区仍可继续使用；需在邮件列表告知维护 IRC-Slack 桥接的成员。</li><li>基金会宣传材料草稿开放审阅，董事会成员尽快反馈。</li><li>8 月不做 Ceph Tech Talk，改为暑期内容推广，并规划新增教育内容页面。</li><li>Q3 的 CSC / 基金会董事会会议将在季度末选定日期，避开选举周期。</li><li>Ceph Developer Summit 定于 8 月 4 日至 13 日，本周开始推广，全程录制。</li><li>各 Ceph Days 活动（韩国、苏黎世、芝加哥、柏林）按既定时间线推进筹备。</li></ul><h2 id="六、下次会议" tabindex="-1">六、下次会议 <a class="header-anchor" href="#六、下次会议" aria-label="Permalink to &quot;六、下次会议&quot;">​</a></h2><p>下一次董事会会议定于 8 月 25 日举行（如无变动）。本次公开会议于太平洋时间上午 10: 34 正式结束。</p>',29)])])}const _=a(t,[["render",r]]);export{u as __pageData,_ as default};
